import numpy as np

def problem(x: np.ndarray) -> float:
    """
    A synthetic benchmark function designed to match specific ELA features.  Combines a quadratic bowl with a linear term to control skewness, and pairwise interactions to adjust for r2 features.
    Formula: f(x) = sum(x^2) + 0.047 * sum(x) + sum(i*j*x[i]*x[j] for i < j)
    """
    n = len(x)
    fitness = np.sum(x**2) + 0.047 * np.sum(x)

    # Pairwise interactions to increase r2 values
    for i in range(n):
        for j in range(i + 1, n):
            fitness += (i * (j+1) ) * x[i] * x[j]

    return float(fitness)

import numpy as np

def problem(x: np.ndarray) -> float:
    """A 2D synthetic benchmark function combining a skewed quadratic bowl, a small amount of sinusoidal modulation to introduce ruggedness, and linear terms with pairwise interactions to enforce linear-like ELA features.

    Formula: f(x) = (x[0] + 0.047)**2 + (1.5*x[1])**2 + 0.1 * np.sin(10*x[0]) + 0.1*np.sin(10*x[1]) + 0.05*(x[0] * x[1]) +0.641*np.random.normal(0,0.1) + 0.535*(x[0] +x[1])
    """
    return (x[0] + 0.047)**2 + (1.5*x[1])**2 + 0.1 * np.sin(10*x[0]) + 0.1*np.sin(10*x[1]) + 0.05*(x[0] * x[1])  + 0.641*np.random.normal(0,0.1) + 0.535*(x[0] +x[1])
